#' Describe age-specific rate patterns
#'
#' `cr_age_pattern()` creates a paragraph describing the age-specific rate
#' pattern for one cancer and one event type from an age-specific rate table
#' generated by `canregtools::create_age_rate()` followed by
#' `canregtools::add_labels()`.
#'
#' @param data A data frame with age-specific rate columns such as `areacode`,
#'   `areacode_cn`, `areacode_en`, `sex`, `cancer`, `cancer_cn`, `cancer_en`,
#'   `agegrp`, `cases`, and `rate`.
#' @param cancer Cancer code, Chinese cancer label, or English cancer label.
#' @param event_type Event type. One of `"incidence"` or `"mortality"`.
#' @param area Main area code or label used for total, male, and female rows.
#' @param area_roles A named list identifying urban and rural rows. Defaults to
#'   `list(urban = 910000, rural = 920000)`.
#' @param lang Language code. One of `"zh"` or `"en"`.
#' @param sex_specific Whether the cancer should be described without sex
#'   stratification. If `NULL`, this is inferred from sex-specific case counts.
#' @param low_rate_threshold Relative threshold for detecting the initial low
#'   rate age span. Consecutive age groups from the youngest age group with
#'   `rate <= peak_rate * low_rate_threshold` are treated as low-level ages.
#' @param sex_dominance_threshold Proportion of age groups required to classify
#'   one sex as generally higher than the other.
#' @param trend_similarity_threshold Spearman correlation threshold for treating
#'   urban and rural age-specific rate trends as similar.
#' @param area_difference_threshold Median relative difference threshold for
#'   treating urban and rural age-specific rates as different.
#' @param digits Number of decimal places for rates.
#'
#' @return A character string.
#' @export
cr_age_pattern <- function(data,
                           cancer,
                           event_type = c("incidence", "mortality"),
                           area,
                           area_roles = list(urban = 910000, rural = 920000),
                           lang = "zh",
                           sex_specific = NULL,
                           low_rate_threshold = 0.05,
                           sex_dominance_threshold = 0.7,
                           trend_similarity_threshold = 0.8,
                           area_difference_threshold = 0.1,
                           digits = 2) {
  event_type <- match.arg(event_type)
  lang <- match.arg(lang, c("zh", "en"))

  if (missing(area) || is.null(area)) {
    stop("`area` must be supplied.", call. = FALSE)
  }

  .cr_validate_age_pattern_data(data)
  .cr_validate_age_pattern_args(
    low_rate_threshold = low_rate_threshold,
    sex_dominance_threshold = sex_dominance_threshold,
    trend_similarity_threshold = trend_similarity_threshold,
    area_difference_threshold = area_difference_threshold,
    digits = digits
  )

  main_total <- .cr_pick_age_rows(data, cancer = cancer, area = area, sex = 0)
  main_male <- .cr_pick_age_rows(data, cancer = cancer, area = area, sex = 1)
  main_female <- .cr_pick_age_rows(data, cancer = cancer, area = area, sex = 2)
  urban_total <- .cr_pick_age_rows(data, cancer = cancer, area = area_roles$urban, sex = 0)
  rural_total <- .cr_pick_age_rows(data, cancer = cancer, area = area_roles$rural, sex = 0)

  if (is.null(sex_specific)) {
    sex_specific <- .cr_age_pattern_is_sex_specific(main_male, main_female)
  }
  sex_specific <- isTRUE(sex_specific)

  template <- .cr_load_template("age_pattern", lang = lang)
  lang_data <- .cr_load_lang(lang)
  event_terms <- .cr_get_event_terms(event_type, lang = lang)
  label_suffix <- .cr_label_suffix(lang)

  peak <- .cr_age_pattern_peak(main_total)
  male_peak <- if (sex_specific) NULL else .cr_age_pattern_peak(main_male)
  female_peak <- if (sex_specific) NULL else .cr_age_pattern_peak(main_female)
  low_span <- .cr_age_pattern_low_span(
    main_total,
    peak_rate = peak$rate,
    threshold = low_rate_threshold,
    lang = lang,
    lang_data = lang_data
  )
  sex_status <- if (sex_specific) {
    "similar"
  } else {
    .cr_age_pattern_sex_status(
      main_male,
      main_female,
      threshold = sex_dominance_threshold
    )
  }
  area_status <- .cr_age_pattern_area_status(
    urban_total,
    rural_total,
    trend_similarity_threshold = trend_similarity_threshold,
    area_difference_threshold = area_difference_threshold
  )
  area_detail <- .cr_age_pattern_area_detail(urban_total, rural_total, lang = lang, lang_data = lang_data)

  cancer_name <- .cr_label_value(main_total[1L, , drop = FALSE], "cancer", label_suffix)
  values <- list(
    cancer_name = cancer_name,
    cancer_name_lower = tolower(cancer_name),
    event_noun = event_terms$noun,
    event_rate_label = event_terms$rate_label,
    age_specific_rate_label = .cr_age_specific_rate_label(event_terms, lang = lang, lang_data = lang_data),
    low_age_span = low_span,
    peak_age_group = .cr_clean_age_group(peak$agegrp, lang = lang, lang_data = lang_data),
    peak_rate = .cr_format_number(peak$rate, digits = digits),
    male_peak_age_group = if (sex_specific) "" else .cr_clean_age_group(male_peak$agegrp, lang = lang, lang_data = lang_data),
    male_peak_rate = if (sex_specific) "" else .cr_format_number(male_peak$rate, digits = digits),
    female_peak_age_group = if (sex_specific) "" else .cr_clean_age_group(female_peak$agegrp, lang = lang, lang_data = lang_data),
    female_peak_rate = if (sex_specific) "" else .cr_format_number(female_peak$rate, digits = digits),
    urban_higher_age_spans = area_detail$urban_higher_age_spans,
    rural_higher_age_spans = area_detail$rural_higher_age_spans,
    phrase_per_100000 = lang_data$phrase$per_100000,
    sex_compare_text = lang_data$sex[[sex_status]]
  )

  values$sex_pattern_text <- if (sex_specific) {
    ""
  } else {
    .cr_render_text(template$sex[[sex_status]], values)
  }
  values$area_summary_text <- .cr_render_text(template$area_summary[[area_detail$summary_key]], values)
  values$area_comparison_text <- .cr_render_text(template$area_comparison[[area_detail$key]], values)
  values$area_pattern_text <- .cr_render_text(template$area[[area_status]], values)

  template_key <- if (sex_specific) "sex_specific" else "default"
  .cr_render_text(template$overall[[template_key]], values)
}

.cr_validate_age_pattern_data <- function(data) {
  required <- c(
    "areacode", "areacode_en", "areacode_cn", "sex", "cancer",
    "cancer_en", "cancer_cn", "agegrp", "cases", "rate"
  )
  .cr_check_required_columns(data, required)
  if (!is.numeric(data$rate)) {
    stop("`rate` must be numeric.", call. = FALSE)
  }
  invisible(data)
}

.cr_validate_age_pattern_args <- function(low_rate_threshold,
                                          sex_dominance_threshold,
                                          trend_similarity_threshold,
                                          area_difference_threshold,
                                          digits) {
  .cr_check_unit_interval(low_rate_threshold, "low_rate_threshold")
  .cr_check_unit_interval(sex_dominance_threshold, "sex_dominance_threshold")
  .cr_check_unit_interval(trend_similarity_threshold, "trend_similarity_threshold")
  .cr_check_unit_interval(area_difference_threshold, "area_difference_threshold")
  if (!is.numeric(digits) || length(digits) != 1L || is.na(digits) || digits < 0L) {
    stop("`digits` must be a non-negative number.", call. = FALSE)
  }
  invisible(TRUE)
}

.cr_check_unit_interval <- function(x, name) {
  if (!is.numeric(x) || length(x) != 1L || is.na(x) || x < 0 || x > 1) {
    stop("`", name, "` must be a number between 0 and 1.", call. = FALSE)
  }
}

.cr_pick_age_rows <- function(data, cancer, area, sex) {
  cancer_values <- as.character(cancer)
  area_values <- as.character(area)

  rows <- data[
    as.character(data$sex) == as.character(sex) &
      (
        as.character(data$cancer) %in% cancer_values |
          as.character(data$cancer_cn) %in% cancer_values |
          as.character(data$cancer_en) %in% cancer_values
      ) &
      (
        as.character(data$areacode) %in% area_values |
          as.character(data$areacode_cn) %in% area_values |
          as.character(data$areacode_en) %in% area_values
      ),
    ,
    drop = FALSE
  ]

  if (nrow(rows) == 0L) {
    stop("No age-specific rate rows found for the requested cancer, area, and sex.", call. = FALSE)
  }

  rows$.age_order <- .cr_age_group_lower(rows$agegrp)
  rows <- rows[order(rows$.age_order), , drop = FALSE]
  rows$.age_order <- NULL
  rows
}

.cr_age_pattern_is_sex_specific <- function(male_rows, female_rows) {
  male_cases <- sum(male_rows$cases, na.rm = TRUE)
  female_cases <- sum(female_rows$cases, na.rm = TRUE)
  isTRUE(male_cases == 0) || isTRUE(female_cases == 0)
}

.cr_age_pattern_peak <- function(rows) {
  valid <- !is.na(rows$rate)
  if (!any(valid)) {
    stop("No non-missing age-specific rate values found.", call. = FALSE)
  }
  rows <- rows[valid, , drop = FALSE]
  row <- rows[which.max(rows$rate), , drop = FALSE]
  list(agegrp = as.character(row$agegrp), rate = row$rate)
}

.cr_age_pattern_low_span <- function(rows, peak_rate, threshold, lang, lang_data) {
  cutoff <- peak_rate * threshold
  is_low <- !is.na(rows$rate) & rows$rate <= cutoff
  if (!any(is_low) || !isTRUE(is_low[1L])) {
    return(.cr_clean_age_group(rows$agegrp[1L], lang = lang, lang_data = lang_data))
  }
  end <- rle(is_low)$lengths[1L]
  first_age <- .cr_age_group_lower(rows$agegrp[1L])
  last_age <- .cr_age_group_upper(rows$agegrp[end])
  .cr_age_span_label(first_age, last_age, lang = lang, lang_data = lang_data)
}

.cr_age_pattern_sex_status <- function(male_rows, female_rows, threshold) {
  merged <- .cr_merge_age_rates(male_rows, female_rows, suffixes = c("_male", "_female"))
  valid <- !is.na(merged$rate_male) & !is.na(merged$rate_female)
  merged <- merged[valid, , drop = FALSE]
  if (nrow(merged) == 0L) return("similar")

  male_prop <- mean(merged$rate_male > merged$rate_female)
  female_prop <- mean(merged$rate_female > merged$rate_male)
  male_burden <- sum(merged$rate_male, na.rm = TRUE)
  female_burden <- sum(merged$rate_female, na.rm = TRUE)
  if (male_prop >= threshold || male_burden > female_burden) {
    "male_higher"
  } else if (female_prop >= threshold || female_burden > male_burden) {
    "female_higher"
  } else {
    "similar"
  }
}

.cr_age_pattern_area_status <- function(urban_rows,
                                        rural_rows,
                                        trend_similarity_threshold,
                                        area_difference_threshold) {
  merged <- .cr_merge_age_rates(urban_rows, rural_rows, suffixes = c("_urban", "_rural"))
  valid <- !is.na(merged$rate_urban) & !is.na(merged$rate_rural)
  merged <- merged[valid, , drop = FALSE]
  if (nrow(merged) < 2L) return("similar")

  trend_cor <- suppressWarnings(stats::cor(merged$rate_urban, merged$rate_rural, method = "spearman"))
  trend_similar <- !is.na(trend_cor) && trend_cor >= trend_similarity_threshold
  denominator <- pmax(abs(merged$rate_urban), abs(merged$rate_rural), .Machine$double.eps)
  relative_diff <- abs(merged$rate_urban - merged$rate_rural) / denominator
  has_difference <- stats::median(relative_diff, na.rm = TRUE) > area_difference_threshold

  if (trend_similar && has_difference) {
    "different_similar"
  } else if (trend_similar) {
    "similar"
  } else {
    "different_trend"
  }
}

.cr_age_pattern_area_detail <- function(urban_rows, rural_rows, lang, lang_data) {
  merged <- .cr_merge_age_rates(urban_rows, rural_rows, suffixes = c("_urban", "_rural"))
  valid <- !is.na(merged$rate_urban) & !is.na(merged$rate_rural)
  merged <- merged[valid, , drop = FALSE]
  if (nrow(merged) == 0L) {
    return(list(
      key = "similar",
      urban_higher_age_spans = "",
      rural_higher_age_spans = ""
    ))
  }

  merged$.age_order <- .cr_age_group_lower(merged$agegrp)
  merged <- merged[order(merged$.age_order), , drop = FALSE]
  comparison <- ifelse(
    merged$rate_urban > merged$rate_rural,
    "urban_higher",
    ifelse(merged$rate_rural > merged$rate_urban, "rural_higher", "similar")
  )
  summary_key <- .cr_age_pattern_area_summary_key(comparison)

  urban_spans <- .cr_age_pattern_comparison_spans(merged$agegrp, comparison, "urban_higher", lang = lang, lang_data = lang_data)
  rural_spans <- .cr_age_pattern_comparison_spans(merged$agegrp, comparison, "rural_higher", lang = lang, lang_data = lang_data)
  key <- if (!identical(urban_spans, "") && !identical(rural_spans, "")) {
    "both"
  } else if (!identical(urban_spans, "")) {
    "urban_higher"
  } else if (!identical(rural_spans, "")) {
    "rural_higher"
  } else {
    "similar"
  }

  list(
    key = key,
    summary_key = summary_key,
    urban_higher_age_spans = urban_spans,
    rural_higher_age_spans = rural_spans
  )
}

.cr_age_pattern_area_summary_key <- function(comparison, threshold = 0.7) {
  comparison <- comparison[comparison %in% c("urban_higher", "rural_higher")]
  if (length(comparison) == 0L) {
    return("similar")
  }

  urban_prop <- mean(comparison == "urban_higher")
  rural_prop <- mean(comparison == "rural_higher")
  if (urban_prop >= threshold) {
    "urban_mostly_higher"
  } else if (rural_prop >= threshold) {
    "rural_mostly_higher"
  } else {
    "mixed"
  }
}

.cr_age_pattern_comparison_spans <- function(agegrp, comparison, target, lang, lang_data) {
  is_target <- comparison == target
  if (!any(is_target)) return("")

  runs <- rle(is_target)
  ends <- cumsum(runs$lengths)
  starts <- ends - runs$lengths + 1L
  spans <- character(0L)
  for (i in seq_along(runs$values)) {
    if (!isTRUE(runs$values[[i]])) next
    first_age <- .cr_age_group_lower(agegrp[starts[[i]]])
    last_age <- .cr_age_group_upper(agegrp[ends[[i]]])
    first_label <- as.character(agegrp[starts[[i]]])
    spans <- c(spans, .cr_age_comparison_span_label(first_age, last_age, first_label, lang = lang, lang_data = lang_data))
  }
  .cr_collapse_age_spans(spans, lang = lang, lang_data = lang_data)
}

.cr_age_comparison_span_label <- function(first_age, last_age, first_label, lang, lang_data) {
  if (!is.infinite(last_age)) {
    return(.cr_age_span_label(first_age, last_age, lang = lang, lang_data = lang_data))
  }

  first_upper <- .cr_age_group_upper(first_label)
  if (identical(lang, "en")) {
    if (is.infinite(first_upper) || first_age == first_upper) {
      paste0(first_age, "+ years")
    } else {
      paste0(first_age, "-", first_upper, "+ years")
    }
  } else {
    if (is.infinite(first_upper) || first_age == first_upper) {
      paste0(first_age, lang_data$phrase$age_and_over_suffix)
    } else {
      paste0(first_age, "-", first_upper, lang_data$phrase$age_and_over_suffix)
    }
  }
}

.cr_collapse_age_spans <- function(x, lang, lang_data) {
  x <- as.character(x)
  len <- length(x)
  if (len == 0L) return("")
  if (len == 1L) return(x)
  if (identical(lang, "en")) {
    if (len == 2L) return(paste(x, collapse = " and "))
    paste0(paste(x[-len], collapse = ", "), ", and ", x[[len]])
  } else {
    paste(x, collapse = lang_data$list$ideographic_comma)
  }
}

.cr_merge_age_rates <- function(x, y, suffixes) {
  x <- x[, c("agegrp", "rate"), drop = FALSE]
  y <- y[, c("agegrp", "rate"), drop = FALSE]
  merge(x, y, by = "agegrp", suffixes = suffixes, sort = FALSE)
}

.cr_age_specific_rate_label <- function(event_terms, lang, lang_data) {
  if (identical(lang, "en")) {
    paste("age-specific", event_terms$rate_label, "rate")
  } else {
    paste0(lang_data$phrase$age_specific_prefix, event_terms$rate_label)
  }
}

.cr_age_group_lower <- function(x) {
  x <- gsub("years|year| ", "", as.character(x), ignore.case = TRUE)
  as.numeric(sub("^([0-9]+).*$", "\\1", x))
}

.cr_age_group_upper <- function(x) {
  x <- gsub("years|year| ", "", as.character(x), ignore.case = TRUE)
  if (grepl("\\+", x)) {
    return(Inf)
  }
  if (grepl("-", x)) {
    return(as.numeric(sub("^[0-9]+-([0-9]+).*$", "\\1", x)))
  }
  as.numeric(sub("^([0-9]+).*$", "\\1", x))
}

.cr_age_span_label <- function(first_age, last_age, lang, lang_data) {
  if (is.infinite(last_age)) {
    return(if (identical(lang, "en")) paste0(first_age, "+ years") else paste0(first_age, lang_data$phrase$age_and_over_suffix))
  }
  if (first_age == last_age) {
    return(if (identical(lang, "en")) paste0(first_age, " years") else paste0(first_age, lang_data$phrase$age_unit))
  }
  if (identical(lang, "en")) paste0(first_age, "-", last_age, " years") else paste0(first_age, "-", last_age, lang_data$phrase$age_unit)
}

.cr_clean_age_group <- function(x, lang, lang_data) {
  lower <- .cr_age_group_lower(x)
  upper <- .cr_age_group_upper(x)
  .cr_age_span_label(lower, upper, lang = lang, lang_data = lang_data)
}